_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":2358,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 8.2\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T5ae,"])self.__next_f.push([1,"Now the word prayāṇa-kāle in this verse is very significant because whatever we do in life will be tested at the time of death. Arjuna is very anxious to know of those who are constantly engaged in Kṛṣṇa consciousness. What should be their position at that final moment? At the time of death all the bodily functions are disrupted, and the mind is not in a proper condition. Thus disturbed by the bodily situation, one may not be able to remember the Supreme Lord. Mahārāja Kulaśekhara, a great devotee, prays, “My dear Lord, just now I am quite healthy, and it is better that I die immediately so that the swan of my mind can seek entrance at the stem of Your lotus feet.” The metaphor is used because the swan, a bird of the water, takes pleasure in digging into the lotus flowers; its sporting proclivity is to enter the lotus flower. Mahārāja Kulaśekhara says to the Lord, “Now my mind is undisturbed, and I am quite healthy. If I die immediately, thinking of Your lotus feet, then I am sure that my performance of Your devotional service will become perfect. But if I have to wait for my natural death, then I do not know what will happen, because at that time the bodily functions will be disrupted, my throat will be choked up, and I do not know whether I shall be able to chant Your name. Better let me die immediately.” Arjuna questions how a person can fix his mind on Kṛṣṇa’s lotus feet at such a time."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":2358,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"2\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 2\",\"advanced_view_url_path\":\"/en/library/bg/8/advanced-view/#bb2092\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/8/2/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/8/2/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/8/2/\"},{\"display_name\":\"Deutsch (German)\",\"language_code\":\"de\",\"enabled\":true,\"url_path\":\"/de/library/bg/8/2/\"},{\"display_name\":\"English\",\"language_code\":\"en\",\"enabled\":true,\"url_path\":\"/en/library/bg/8/2/\"},{\"display_name\":\"Español (Spanish)\",\"language_code\":\"es\",\"enabled\":true,\"url_path\":\"/es/library/bg/8/2/\"},{\"display_name\":\"Eesti ke