e_code\":\"sk\",\"enabled\":true,\"url_path\":\"/sk/library/bg/8/3/\"},{\"display_name\":\"Slovenščina (Slovenian)\",\"language_code\":\"sl\",\"enabled\":true,\"url_path\":\"/sl/library/bg/8/3/\"},{\"display_name\":\"Українська мова (Ukrainian)\",\"language_code\":\"uk\",\"enabled\":true,\"url_path\":\"/uk/library/bg/8/3/\"},{\"display_name\":\"isiZulu (Zulu)\",\"language_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/8/\",\"title\":\"Chapter Eight: Attaining the Supreme\"}],\"url_path\":\"/en/library/bg/8/3/\",\"bb\":2099,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/8/2/\",\"title\":\"TEXT 2\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/8/4/\",\"title\":\"TEXT 4\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":2367,\"bb\":568182,\"url_path\":\"/en/library/bg/8/3/devanagari/\",\"body_final\":\"श्रीभगवानुवाच
अक्षरं ब्रह्म परमं स्वभावोऽध्यात्ममुच्यते ।
भूतभावोद्भ‍वकरो विसर्ग: कर्मसंज्ञित: ॥ ३ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":2368,\"bb\":2101,\"url_path\":\"/en/library/bg/8/3/b2101/\",\"body_value\":\"śrī-bhagavān uvāca
akṣaraṁ brahma paramaṁ
svabhāvo ’dhyātmam ucyate
bhūta-bhāvodbhava-karo
visargaḥ karma-saṁjñitaḥ\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":2369,\"bb\":2102,\"url_path\":\"/en/library/bg/8/3/b2102/\",\"shadow_value\":\"śrī-bhagavān uvāca – the Supreme Personality of Godhead said; akṣaram – indestructible; brahma – Brahman; paramam – transcendental; svabhāvaḥ – eternal nature; adhyātmam – the self; ucyate – is called; bhūta-bhāva-udbhava-karaḥ – producing the material bodies of the living entities; visargaḥ – creation; karma – fruitive activities; saṁjñitaḥ – is called.\",\"word_for_word_value\":[{\"word\":\"śrī-bhagavān uvāca\",\"translation\":\"the Supreme Personality of Godhead said\"},{\"word\":\"akṣaram\",\"translation\":\"indestructible\"},{\"word\":\"brahma\",\"translation\":\"Brahman\"},{\"word\":\"paramam\",\"translation\":\"transcendental\"},{\"word\":\"svabhāvaḥ\",\"translation\":\"eternal nature\"},{\"word\":\"adhyātmam\",\"translation\":\"the self\"},{\"word\":\"ucyate\",\"translation\":\"is called\"},{\"word\":\"bhūta-bhāva-udbhava-karaḥ\",\"translation\":\"producing the material bodies of the living entities\"},{\"word\":\"visargaḥ\",\"translation\":\"creation\"},{\"word\":\"karma\",\"translation\":\"fruitive activities\"},{\"word\":\"saṁjñitaḥ\",\"translation\":\"is called\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":2370,\"bb\":2103,\"url_path\":\"/en/library/bg/8/3/b2103/\",\"body_value\":\"The Supreme Personality of Godhead said: The indestructible, transcendental living entity is called Brahman, and his eternal nature is called adhyātma, the self. Action pertaining to the development of the material bodies of the living entities is called karma, or fruitive activities.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2371,\"bb\":2104,\"url_path\":\"/en/library/bg/8/3/b2104/\",\"body_value\":\"Brahman is indestructible and eternally existing, and its constitution is not changed at any time. But beyond Brahman there is Para-brahman. Brahman refers to the living entity, and Para-brahman refers to the Supreme Personality of Godhead. The constitutional position of the living entity is different from the position he takes in the material world. In material consciousness his nature is to try to be the lord of matter, but in spiritual consciousness, Kṛṣṇa consciousness, his position is to serve the Supreme. When the living entity is in material consciousness, he has to take on various bodies in the material world. That is called karma, or varied creation by the force of material consciousness.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2372,\"bb\":2105,\"url_path\":\"/en/library/bg/8/3/b2105/\",\"body_value\":\"In Vedic literature the living entity is called jīvātmā and Brahman, but he is never called Para-brahman. The living entity (jīvātmā) takes different positions – sometimes he merges into the dark material nature and identifies himself with matter, and sometimes he identifies himself with the superior, spiritual nature. Therefore he is called the Supreme Lord’s marginal energy. According to his identification with material or spiritual nature, he receives a material or spiritual body. In material nature he may take a body from any of the 8,400,000 species of life, but in spiritual nature he has only one body. In material nature he is manifested sometimes as a man, demigod, animal, beast, bird, etc., according to his karma. To attain material heavenly planets and enjoy their facilities, he sometimes performs sacrifices (yajña), but when his merit is exhausted he returns to earth again in the form of a man. This process is called karma.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2373,\"bb\":2106,\"url_path\":\"/en/library/bg/8/3/b2106/\",\"body_value\":\"The Chāndogya Upaniṣad describes the Vedic sacrificial process. On the sacrificial altar, five kinds of offerings are made into five kinds of fire. The five kinds of fire are conceived of as the heavenly planets, clouds, the earth, man and woman, and the five kinds of sacrificial offerings are faith, the enjoyer on the moon, rain, grains and semen.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2374,\"bb\":2107,\"url_path\":\"/en/library/bg/8/3/b2107/\",\"body_value\":\"In the process of sacrifice, the living entity makes specific sacrifices to attain specific heavenly planets and consequently reaches them. When the merit of sacrifice is exhausted, the living entity descends to earth in the form of rain, then takes on the form of grains, and the grains are eaten by man and transformed into semen, which impregnates a woman, and thus the living entity once again attains the human form to perform sacrifice and so repeat the same cycle. In this way, the living entity perpetually comes and goes on the material path. The Kṛṣṇa conscious person, however, avoids such sacrifices. He takes directly to Kṛṣṇa consciousness and thereby prepares himself to return to Godhead.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2375,\"bb\":2108,\"url_path\":\"/en/library/bg/8/3/b2108/\",\"body_value\":\"Impersonalist commentators on the Bhagavad-gītā unreasonably assume that Brahman takes the form of jīva in the material world, and to substantiate this they refer to Chapter Fifteen, verse 7, of the Gītā. But in this verse the Lord also speaks of the living entity as “an eternal fragment of Myself.” The fragment of God, the living entity, may fall down into the material world, but the Supreme Lord (Acyuta) never falls down. Therefore this assumption that the Supreme Brahman assumes the form of jīva is not acceptable. It is important to remember that in Vedic literature Brahman (the living entity) is distinguished from Para-brahman (the Supreme Lord).\"}]}],\"short_title\":\"Bg. 8.3\",\"medium_title\":\"Bhagavad-gītā As It Is 8.3\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L25\",\"$L26\",\"$L27\"]}]\n"])self.__next_f.push([1,"29:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n2f:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n25:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-8 text-base\",\"children\":[\"$\",\"ol\",null,{\"children\":[[\"$\",\"li\",\"/en/library/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/\",\"className\":\"text-vb-link\",\"children\":\"Library\"}],\" » \"]}],[\"$\",\"li\",\"/en/library/bg/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/bg/\",\"className\":\"text-vb-link\",\"children\":\"Bhagavad-gītā As It Is\"}],\" » \"]}],[\"$\",\"li\",\"/en/library/bg/8/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/bg/8/\",\"className\":\"text-vb-link\",\"children\":\"Chapter Eight: Attaining the Supreme\"}],false]}]]}]}],[\"$\",\"main\",null,{\"children\":[\"$L28\",[\"$\",\"div\",null,{\"children\":[[\"$\",\"$L29\"